const course: DeepCourse = {"slug":"bookkeeping-basics","title":"Bookkeeping Basics (Xero & QBO)","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Career skill · Pro</p><h1 class=\"display-lg mt-4\">Bookkeeping Basics (Xero & QBO)<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Keep small-business books clean, traceable, and ready for an accountant without pretending to be one.</p><div class=\"mt-8 flex flex-wrap gap-2.5\"><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold border\">6-question quiz</span></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Small businesses need their money records kept clean far more often than they need an accountant. This course teaches the bookkeeping layer — invoices, bills, reconciliation — in Xero and QuickBooks.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You’re precise, trustworthy and genuinely fine with routine. In bookkeeping, boring is a feature.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">The monthly bookkeeping rhythm, debits and credits explained like a human, and a clear line for when to hand off to an accountant.</p></div></div></div></div></section>"},{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto grid max-w-5xl gap-10 md:grid-cols-2\"><div><p class=\"eyebrow\">The job</p><h2>Clean books are a decision system.</h2><p>A bookkeeping VA records and organizes the evidence behind a small business: bank activity, invoices, bills, payments, and reconciliations. Your job is to make the file understandable to the owner and reviewable by the accountant.</p></div><div><p class=\"eyebrow\">The work</p><p>You will maintain a chart of accounts, capture bills, issue invoices, reconcile bank and card accounts, investigate exceptions, manage AP and AR routines, prepare close support, and communicate questions precisely.</p><p>Bookkeeping rewards careful judgment more than speed. The best beginner signal is not claiming tax expertise; it is leaving a clean audit trail, asking a good question, and refusing to guess.</p></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://quickbooks.intuit.com/learn-support/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">QuickBooks Learn &amp; Support</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Official training for the software in most US bookkeeping ads.</p></a></li><li class=\"h-full\"><a href=\"https://central.xero.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Xero Central</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The AU/NZ equivalent. Free courses and certification.</p></a></li><li class=\"h-full\"><a href=\"https://www.youtube.com/@AccountingStuff\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Accounting Stuff on YouTube</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Debits and credits explained better than most paid courses.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section id=\"tools\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Tools</p><h2>Learn the stack. Do not worship it.</h2><p>Clients commonly use Xero or QuickBooks Online, plus Dext, Hubdoc, Stripe, PayPal, Shopify, and spreadsheets. Learn navigation, but focus on controls: source documents, approval, reconciliations, lock dates, and clear exception lists.</p><div class=\"grid gap-4 md:grid-cols-3\"><div class=\"rounded-2xl border p-5\"><h3>Xero</h3><p>Bank feeds, bills, reconciliations, tracking categories, and advisor review.</p></div><div class=\"rounded-2xl border p-5\"><h3>QuickBooks Online</h3><p>Bank rules, chart of accounts, projects/classes, and reporting.</p></div><div class=\"rounded-2xl border p-5\"><h3>Dext / Hubdoc</h3><p>Receipt capture and document storage; they support, not replace, careful coding.</p></div></div></div></section>"},{"kind":"html","value":"<section id=\"rates\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Rates</p><h2>Price the outcome and the risk.</h2><p>PH bookkeeping VA roles often sit around US$800–1,600 monthly depending on volume, QBO/Xero confidence, complexity, close responsibility, and supervision. Entry hourly work can be lower; a clean monthly close, AP ownership, or ecommerce reconciliation moves the rate because errors cost the client money.</p><p>Do not price “reconcile the books” until you know the entities, accounts, transaction volume, backlog, bank feeds, ecommerce/payment processors, payroll boundary, and who answers questions. A messy catch-up is a different project from a monthly routine.</p></div></section>"},{"kind":"html","value":"<section id=\"first-client\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">First client</p><h2>Make a small, believable promise.</h2><p>Build a fictional close with bank activity, invoices, bills, a duplicate, a prepayment, and an unanswered item. Deliver the reconciliation support, P&L, cash summary, and three owner questions. It proves care without claiming you are the tax adviser.</p><ol><li>Use a sample company or trial file, never a real client file without authorization.</li><li>Enter and reconcile one month while retaining the source for every decision.</li><li>Write the owner questions with account, date, amount, document, and recommended next step.</li></ol></div></section>"},{"kind":"html","value":"<section id=\"red-flags\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Red flags</p><h2>Walk away early.</h2><div class=\"grid gap-4 md:grid-cols-2\"><div class=\"rounded-2xl border border-red-200 p-5\"><h3>“Just make it reconcile”</h3><p>A plug to miscellaneous income hides an error. Leave an open, documented question instead.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Tax advice outside your role</h3><p>Record evidence and raise questions; do not sign filings or make tax treatment promises without authority.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Shared bank logins</h3><p>Use the client’s approved access and least privilege. Financial access needs clear ownership.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>No receipts, no answers</h3><p>Set a cutoff and query list. You cannot create a defensible close from missing evidence.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Backlog called “one day of work”</h3><p>Request account count, transaction volume, last reconciliation date, and sample statements before quoting.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>One person approves and pays</h3><p>Flag missing controls. Payment preparation and approval should be separated where possible.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Changing locked periods</h3><p>Ask why and preserve the audit trail. Silent history changes ruin review.</p></div></div></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<section class=\"px-5 py-20 md:px-8\"><div class=\"mx-auto max-w-5xl rounded-3xl bg-ink p-8 text-paper md:p-12\"><p class=\"eyebrow\">Your next move</p><h2>Do one real bookkeeping va task this week.</h2><p>Close one fictional month to the cent, leave every exception visible, and write three good questions. That is the quiet competence clients will pay to keep.</p><a class=\"button\" href=\"/courses\">Build your proof</a></div></section>"}],"modules":[{"n":1,"title":"Understand the ledger before touching the bank feed","outcome":"Classify the five account types and the story behind a transaction.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Classify the five account types and the story behind a transaction.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Assets, liabilities, equity, income, and expenses are categories, not guesses. The same bank payment can mean an expense, loan repayment, owner draw, transfer, or asset purchase depending on evidence.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a trimmed chart of accounts and source documents, not memory of a bank description.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A US$1,200 payment says only “TRANSFER.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You do not code it as income because money arrived. You check the source account and owner note; it may be a transfer between accounts or a loan contribution. The ledger must describe what happened.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the five account types.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Classify three sample transactions.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">State what source would prove each classification.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Understand the ledger before touching the bank feed”. The honest answer is:","options":["Classify the five account types and the story behind a transaction.","Run a close checklist with evidence, owner, and reviewer.","Capture bills, approval, due dates, and payment status cleanly.","Create a simple account structure that supports reporting."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Invoice accurately, apply payments, and identify cash risk.","Capture bills, approval, due dates, and payment status cleanly.","Package a monthly bookkeeping rhythm clients can understand.","Standardise data while keeping an auditable route back to the source and every important transformation."],"answer":3,"explain":"That one is from “Data Entry & Research VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Understand the ledger before touching the bank feed”, what do you do first?","options":["Classify three sample transactions.","State what source would prove each classification.","Write the five account types."],"answer":2,"explain":"Order protects the outcome here: “Write the five account types.” comes before everything else, or the rest is guesswork."}]},{"n":2,"title":"Build a chart of accounts people can use","outcome":"Create a simple account structure that supports reporting.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Create a simple account structure that supports reporting.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A chart of accounts should reflect how the owner makes decisions. Too many vague accounts create false precision; too few hide useful differences. Keep naming consistent and ask before adding a new category.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use Xero/QBO account settings, account numbers only when useful, and a change log.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A marketing agency has separate subscriptions, contractor costs, and advertising spend.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You retain categories that show gross margin and controllable spend, but do not make separate accounts for every tiny software tool. The owner can see the business without a 90-line P&L.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Review existing accounts.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Mark duplicates and vague categories.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Propose additions with a reporting reason.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Build a chart of accounts people can use” is building toward?","options":["Package a monthly bookkeeping rhythm clients can understand.","Create a simple account structure that supports reporting.","Invoice accurately, apply payments, and identify cash risk.","Match bank activity to the ledger and investigate differences."],"answer":1,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Classify the five account types and the story behind a transaction.","Invoice accurately, apply payments, and identify cash risk.","You can automate the obvious wins and document them so the business does not quietly become dependent on your memory.","Ask precise questions and stay within your authority."],"answer":2,"explain":"That one is from “Becoming an Operations Lead”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Build a chart of accounts people can use”, what do you do first?","options":["Mark duplicates and vague categories.","Propose additions with a reporting reason.","Review existing accounts."],"answer":2,"explain":"Order protects the outcome here: “Review existing accounts.” comes before everything else, or the rest is guesswork."}]},{"n":3,"title":"Reconcile without making the screen green","outcome":"Match bank activity to the ledger and investigate differences.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Match bank activity to the ledger and investigate differences.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reconciliation proves that recorded activity agrees with an external statement for a defined period. Suggested matches save clicks; they do not transfer responsibility.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use bank feeds, reconciliation reports, statement PDFs, and a query list.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The statement ends at 219,583 but the ledger is 227,483.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You find an unexplained debit and a duplicated contractor payment. You do not force a match. You retain the evidence, reverse the duplicate if supported, and send the unexplained item to the owner.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Reconcile oldest first.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">List unmatched items separately.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Save the final reconciliation report.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Reconcile without making the screen green”. What should you now be able to do?","options":["Invoice accurately, apply payments, and identify cash risk.","Package a monthly bookkeeping rhythm clients can understand.","Match bank activity to the ledger and investigate differences.","Classify the five account types and the story behind a transaction."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Classify the five account types and the story behind a transaction.","Create a simple account structure that supports reporting.","Write first touches people answer","Invoice accurately, apply payments, and identify cash risk."],"answer":2,"explain":"That one is from “Sales & Lead Generation VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Reconcile without making the screen green”, what do you do first?","options":["Reconcile oldest first.","Save the final reconciliation report.","List unmatched items separately."],"answer":0,"explain":"Order protects the outcome here: “Reconcile oldest first.” comes before everything else, or the rest is guesswork."}]},{"n":4,"title":"Run accounts payable with controls","outcome":"Capture bills, approval, due dates, and payment status cleanly.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Capture bills, approval, due dates, and payment status cleanly.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AP is not merely typing bills. It protects cash and prevents duplicate or unauthorized payments. Capture vendor, invoice number, date, due date, tax treatment as directed, approval, and evidence.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use bills, receipt capture, approval status, and an AP aging report.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A vendor sends the same invoice twice from two email addresses.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You check invoice number, amount, and purchase evidence before entering it. The second email becomes a documented duplicate, not a second bill. A fixed payment run makes this easier to catch.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Enter a sample bill with evidence.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Set one approval owner.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Create a weekly payment-run list.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Run accounts payable with controls”. The honest answer is:","options":["Capture bills, approval, due dates, and payment status cleanly.","Run a close checklist with evidence, owner, and reviewer.","Ask precise questions and stay within your authority.","Classify the five account types and the story behind a transaction."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Use a monthly evidence trail to earn broader ownership, a clearer role, and a stronger rate.","Match bank activity to the ledger and investigate differences.","Create a simple account structure that supports reporting.","Package a monthly bookkeeping rhythm clients can understand."],"answer":0,"explain":"That one is from “General Virtual Assistant”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Run accounts payable with controls”, what do you do first?","options":["Create a weekly payment-run list.","Set one approval owner.","Enter a sample bill with evidence."],"answer":2,"explain":"Order protects the outcome here: “Enter a sample bill with evidence.” comes before everything else, or the rest is guesswork."}]},{"n":5,"title":"Manage receivables without awkward chasing","outcome":"Invoice accurately, apply payments, and identify cash risk.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Invoice accurately, apply payments, and identify cash risk.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AR is the difference between a sale and cash in the bank. Issue invoices from the agreed scope, record payment against the right customer and invoice, and use an aging report to prioritize follow-up.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use recurring invoices, payment links, invoice status, and AR aging.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A customer paid 3,000 with no invoice number in the reference.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You compare amount, date, customer history, and open invoices; if uncertain, you leave it unapplied and ask. Applying money to the wrong invoice makes the aging report lie.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Create a sample invoice.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Apply one confirmed payment.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Draft a factual 30-day reminder.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Manage receivables without awkward chasing” is building toward?","options":["Invoice accurately, apply payments, and identify cash risk.","Create a simple account structure that supports reporting.","Ask precise questions and stay within your authority.","Capture bills, approval, due dates, and payment status cleanly."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["You can run a crawl, turn it into a prioritised issue log, and know exactly which fixes need someone senior to approve.","Classify the five account types and the story behind a transaction.","Run a close checklist with evidence, owner, and reviewer.","Capture bills, approval, due dates, and payment status cleanly."],"answer":0,"explain":"That one is from “SEO Specialist VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Manage receivables without awkward chasing”, what do you do first?","options":["Draft a factual 30-day reminder.","Create a sample invoice.","Apply one confirmed payment."],"answer":1,"explain":"Order protects the outcome here: “Create a sample invoice.” comes before everything else, or the rest is guesswork."}]},{"n":6,"title":"Close a month in dependency order","outcome":"Run a close checklist with evidence, owner, and reviewer.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Run a close checklist with evidence, owner, and reviewer.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Month-end is a sequence: obtain documents, reconcile cash, resolve exceptions, review AR/AP, process approved recurring or adjusting entries, review unusual movements, and present reports. The close is not done because all tasks are ticked; it is done because it can be reviewed.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a close tracker, account reconciliations, supporting schedules, and lock dates.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Stripe deposits net sales, fees, and refunds into one payout.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You do not call the deposit “sales.” You reconcile the payout to its underlying activity, identify fees and refunds separately under the client’s setup, and retain the payout report.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Set close days and owners.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Complete cash before reporting.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Lock a reviewed period per client policy.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Close a month in dependency order”. What should you now be able to do?","options":["Create a simple account structure that supports reporting.","Package a monthly bookkeeping rhythm clients can understand.","Classify the five account types and the story behind a transaction.","Run a close checklist with evidence, owner, and reviewer."],"answer":3,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Classify the five account types and the story behind a transaction.","Ask precise questions and stay within your authority.","You can run a transaction board that tracks every deadline and document, and escalate the right things to the agent before they become problems.","Package a monthly bookkeeping rhythm clients can understand."],"answer":2,"explain":"That one is from “Real Estate VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Close a month in dependency order”, what do you do first?","options":["Set close days and owners.","Lock a reviewed period per client policy.","Complete cash before reporting."],"answer":0,"explain":"Order protects the outcome here: “Set close days and owners.” comes before everything else, or the rest is guesswork."}]},{"n":7,"title":"Work safely with accountants and owners","outcome":"Ask precise questions and stay within your authority.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Ask precise questions and stay within your authority.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A bookkeeper prepares clean evidence and raises exceptions. The accountant makes accounting, tax, and filing decisions within their engagement. Your question should include period, account, amount, source, and what you already checked.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use an exception log, advisor notes, and client-approved communication channels.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A client paid twelve months of software in January.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You record the payment with the invoice and ask the accountant whether they want a prepayment schedule and monthly release. You do not decide tax treatment from a tutorial.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Frame one question with evidence.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Separate bookkeeping from tax advice.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Record the accountant’s approved treatment.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Work safely with accountants and owners”. The honest answer is:","options":["Match bank activity to the ledger and investigate differences.","Capture bills, approval, due dates, and payment status cleanly.","Package a monthly bookkeeping rhythm clients can understand.","Ask precise questions and stay within your authority."],"answer":3,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Capture bills, approval, due dates, and payment status cleanly.","You can describe VA work in terms of outcomes a business pays for, and you know which myths to drop before they cost you money.","Package a monthly bookkeeping rhythm clients can understand.","Match bank activity to the ledger and investigate differences."],"answer":1,"explain":"That one is from “The Complete VA Starter”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Work safely with accountants and owners”, what do you do first?","options":["Separate bookkeeping from tax advice.","Frame one question with evidence.","Record the accountant’s approved treatment."],"answer":1,"explain":"Order protects the outcome here: “Frame one question with evidence.” comes before everything else, or the rest is guesswork."}]},{"n":8,"title":"Turn accurate work into a reliable service","outcome":"Package a monthly bookkeeping rhythm clients can understand.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Package a monthly bookkeeping rhythm clients can understand.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A monthly service has a cutoff, document routine, coding/reconciliation process, exception deadline, reports, review, and archive. Sell the rhythm and the evidence, not a vague promise to “keep books updated.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a monthly timeline, scope sheet, and owner-ready report pack.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A new client has two banks, one card, Xero, and a monthly invoice run.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You scope volume, name the cutoff, list what they must send, set the close date, define included questions and reports, and state what requires accountant approval. The client sees a process before they see a price.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Time a sample monthly close.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Make a scope checklist.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Create an owner report with cash, P&L, and open questions.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Turn accurate work into a reliable service” is building toward?","options":["Package a monthly bookkeeping rhythm clients can understand.","Run a close checklist with evidence, owner, and reviewer.","Invoice accurately, apply payments, and identify cash risk.","Match bank activity to the ledger and investigate differences."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Match bank activity to the ledger and investigate differences.","Run a close checklist with evidence, owner, and reviewer.","Set up one reliable place for requests, decisions, deadlines, and the work that is waiting on someone else.","Classify the five account types and the story behind a transaction."],"answer":2,"explain":"That one is from “General Virtual Assistant”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Turn accurate work into a reliable service”, what do you do first?","options":["Time a sample monthly close.","Create an owner report with cash, P&L, and open questions.","Make a scope checklist."],"answer":0,"explain":"Order protects the outcome here: “Time a sample monthly close.” comes before everything else, or the rest is guesswork."}]}],"quiz":[{"q":"What should you do with an unmatched bank transaction?","options":["Code it to miscellaneous","Investigate and leave it on a query list","Delete it","Match the closest amount"],"answer":1,"explain":"An open documented item is safer than a false match."},{"q":"Why reconcile a bank account?","options":["To make a dashboard green","To compare ledger activity with an external statement","To calculate tax automatically","To delete old transactions"],"answer":1,"explain":"Reconciliation is evidence that the records agree for a period."},{"q":"What is the safest AP control?","options":["Pay bills whenever they arrive","Capture evidence, approval, and a fixed payment run","Let one person create and approve every bill","Trust email subject lines"],"answer":1,"explain":"Documented approval and a routine help prevent duplicates and surprise payments."},{"q":"A yearly software payment may be what?","options":["Always an immediate expense","A prepayment requiring accountant-approved treatment","Customer income","Equity"],"answer":1,"explain":"The bookkeeper records evidence and asks for approved treatment when needed."},{"q":"What belongs in a question to an accountant?","options":["“What do I do?”","Account, period, amount, source, and checks completed","Only a screenshot","A guess presented as fact"],"answer":1,"explain":"Specific questions reduce back-and-forth and preserve the audit trail."},{"q":"Why lock a reviewed period?","options":["To stop future business","To prevent silent changes to reconciled history","To remove audit evidence","To avoid reports"],"answer":1,"explain":"Locking preserves a reviewable record."}],"glossary":[{"term":"Chart of accounts","def":"The organized list of accounts used to classify transactions."},{"term":"Asset","def":"A resource the business controls, such as cash or equipment."},{"term":"Liability","def":"An obligation the business owes."},{"term":"Equity","def":"The owner’s residual interest in the business."},{"term":"Reconciliation","def":"Matching ledger activity to an external account statement."},{"term":"Accounts payable","def":"Amounts the business owes suppliers."},{"term":"Accounts receivable","def":"Amounts customers owe the business."},{"term":"Aging report","def":"A report grouping unpaid balances by how overdue they are."},{"term":"Prepayment","def":"A payment for future benefit that may be released over time."},{"term":"Journal entry","def":"A formal ledger entry, often supporting an adjustment."},{"term":"Close","def":"The controlled process of completing a reporting period."},{"term":"Audit trail","def":"The documents and history that explain a recorded decision."}]};

export default course;
